<?php
namespace App\Application\Documentos;
use App\Application\Autorizacion\AutorizacionContextual; use App\Application\Contexto\ContextoOperativo; use App\Models\{Documento,DocumentoVersion,User}; use Illuminate\Auth\Access\AuthorizationException; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
final class RechazarVersionDocumento { public function __construct(private readonly AutorizacionContextual $a,private readonly ConsultaDocumentosContextuales $q,private readonly RegistrarActuacionDocumento $h){} public function ejecutar(ContextoOperativo $c,User $u,Documento $d,DocumentoVersion $v,string $observacion):void{$d=$this->q->resolver($c,$d->id);$v=$this->q->resolverVersion($c,$d,$v->id);if(!$this->a->tienePermiso($c,'documentos.aprobar'))throw new AuthorizationException();if(blank($observacion))throw ValidationException::withMessages(['observacion_rechazo'=>['La observación de rechazo es obligatoria.']]);DB::transaction(function()use($d,$v,$u,$observacion){Documento::query()->whereKey($d->id)->lockForUpdate()->firstOrFail();$v=DocumentoVersion::query()->whereKey($v->id)->lockForUpdate()->firstOrFail();if($v->estado->value!=='pendiente_aprobacion')throw ValidationException::withMessages(['version'=>['Solo se puede rechazar una Versión pendiente.']]);$v->update(['estado'=>'rechazada','rechazada_por_user_id'=>$u->id,'nombre_rechazador'=>$u->name,'rechazada_at'=>now(),'observacion_rechazo'=>$observacion]);$this->h->registrar($d,$v,$u,'version_rechazada','Rechazó la Versión.');});}}
